mapper.select:
SELECT *
FROM baseline_report_export
WHERE trigger_user_id = #{triggerUserId}
  AND project_id = #{projectId}
  AND baseline_id = #{baselineId}
  AND status IN ('PENDING', 'RUNNING')
ORDER BY id DESC
LIMIT 1

mapper.update:
UPDATE baseline_report_export
SET updated_at = NOW()
WHERE id = #{id}
  AND worker_id = #{workerId}
  AND status = 'RUNNING'
